-- ════════════════════════════════════════════════════════════════════
-- Kosh MFS — demo data: 4 more accounts per role and the transaction
-- history of every account. Run once in the Supabase SQL Editor, AFTER
-- schema.sql and seed.sql.
--
-- With seed.sql this gives 5 accounts per role. Sign in with:
--   password demo@1234   PIN 24680   (every account below)
--
--   Role      Name            Phone        District     Outlet / business
--   PERSONAL  Ashraful Islam  01700000001  —
--   PERSONAL  Arif Sheikh     01453384498  —
--   PERSONAL  Rahim Haque     01953805977  —
--   PERSONAL  Karim Begum     01355258360  —
--   PERSONAL  Rakib Uddin     01357298253  —
--   AGENT     Sabbir_Tele     01814557644  Dhaka
--   AGENT     Tamim Bhuiyan   01462061206  Dhaka        Bhuiyan Store
--   AGENT     Sharmin Sarkar  01364232142  Chattogram   Sharmin Enterprise
--   AGENT     Mitu Talukder   01764743977  Gazipur      Mitu Enterprise
--   AGENT     Arif Uddin      01765278926  Narayanganj  Arif Enterprise
--   MERCHANT  Nafiztong       01773519331  Dhaka
--   MERCHANT  Arif Roy        01880438058  Dhaka        Kacchi House Dhanmondi
--   MERCHANT  Hasan Rahman    01485360573  Chattogram   Daily Needs Panchlaish
--   MERCHANT  Saiful Islam    01588238447  Gazipur      Ma Grocery Board Bazar
--   MERCHANT  Keya Rahman     01780178082  Narayanganj  Arogya Medicine Corner Fatullah
--   ADMIN     Platform Admin  admin@example.com (password Demo@1234, 2FA on)
--
-- The new accounts come from scripts/seed-synthetic.mjs, exported on 2026-10-03, so the history
-- ends on that day; the intelligence pages look at the last 30 days, so
-- their patterns fade as the dates age. For fresh dates run instead:
--   node --env-file=.env.local scripts/seed-synthetic.mjs --reset
--   node --env-file=.env.local scripts/seed-synthetic.mjs
--
-- The seed.sql accounts take part in this history: Ashraful Islam,
-- Sabbir_Tele and Nafiztong get their wallets adjusted by exactly its effect
-- (added on top of whatever they hold now) plus an opening balance, and the
-- agent and merchant get a district.
-- Amounts are in paisa (100 = ৳1).
-- ════════════════════════════════════════════════════════════════════

begin;

do $$
begin
  if exists (select 1 from users where id like 'syn\_%') or exists (select 1 from transactions where id like 'txn\_smp\_%') then
    raise exception 'The demo data is already there — this script only runs once.';
  end if;
  if (select count(*) from wallets where user_id in ('usr_ashraful', 'usr_sabbir_tele', 'usr_nafiztong')) <> 3 then
    raise exception 'Run seed.sql first: the starting accounts are missing.';
  end if;
end $$;

-- users (12)

-- personal_profiles (4)

-- agent_profiles (4)

-- merchant_profiles (4)

-- merchant_businesses (4)

-- account_status_history (24)

-- wallets (12)

-- transactions (1567)

-- commissions (325)

-- Opening balances: the money these accounts held before the history starts
-- (without them a balance would dip below zero part-way through).
update wallets set available = available + 600000 where user_id = 'usr_ashraful';  -- +৳6,000 e-money
update wallets set cash_in_hand = cash_in_hand + 1500000 where user_id = 'usr_sabbir_tele';  -- +৳15,000 outlet cash

-- The history's effect on the seed.sql accounts (same rules as the app's ledger).
with eff as (
  select user_id, sum(avail)::bigint avail, sum(cash)::bigint cash
  from transactions t
  cross join lateral (values
    (t.sender_user_id,      -(t.amount + t.sender_fee), 0::bigint),
    (t.receiver_user_id,    t.amount - t.receiver_fee,  0::bigint),
    (t.commission_user_id,  coalesce(t.commission_amount, 0), 0::bigint),
    (t.cash_effect_user_id, 0::bigint, coalesce(t.cash_effect_delta, 0))
  ) e(user_id, avail, cash)
  where (t.id like 'syn\_%' or t.id like 'txn\_smp\_%') and t.status in ('SUCCESSFUL', 'REFUNDED')
    and e.user_id in ('usr_ashraful', 'usr_sabbir_tele', 'usr_nafiztong')
  group by user_id
)
update wallets w
   set available = w.available + eff.avail,
       cash_in_hand = case when w.cash_in_hand is null then null else w.cash_in_hand + eff.cash end,
       version = w.version + 1, updated_at = now()
  from eff
 where w.user_id = eff.user_id;

do $$
begin
  if exists (select 1 from wallets where available < 0 or coalesce(cash_in_hand, 0) < 0) then
    raise exception 'A balance would go negative — nothing was changed.';
  end if;
end $$;

update agent_profiles set district = 'Dhaka', area = 'Mirpur' where user_id = 'usr_sabbir_tele';
update merchant_businesses set district = 'Dhaka', area = 'Dhanmondi' where user_id = 'usr_nafiztong';

commit;

-- Result.
select u.role, u.name, u.phone, w.available / 100.0 as balance_taka, w.cash_in_hand / 100.0 as outlet_cash_taka
from users u join wallets w on w.user_id = u.id
order by u.role, u.name;
